/* ==================================================================
   Territoires de RÉGULATION — ceux que l'on retrouve côté utilisateurs
   (territoires de gestion, territoire du régulateur) et côté offre de soins.
   Par défaut : 1 territoire de régulation = 1 territoire SAS.
   Exception : un territoire de régulation = une liste de territoires SAS.
   Stockage partagé entre les pages (localStorage, clé REG_KEY).
   ================================================================== */
const SAS_BY_CODE = Object.fromEntries(SAS_REFERENTIEL.map(s => [s.code, s]));
const REG_KEY = "bo-sas-territoires-regulation-v1";

/* « SAS 75 » → « SAS-75 » (code du territoire de régulation par défaut) */
function sasSuffix(code) { return String(code).replace(/^SAS\s*/, ""); }
function defaultRegCode(sasCode) { return "SAS-" + sasSuffix(sasCode); }
function sasShortLabel(s) {
  return s.depLabel + (s.villeRef ? " (" + s.villeRef + ")" : "");
}

/* Seed : un territoire de régulation par SAS, sauf l'exemple de regroupement ci-dessous
   (EXEMPLE MAQUETTE — à remplacer par les vrais regroupements). */
const REG_SEED_GROUPS = [
  { code: "SAS-20", nom: "SAS 20 · Corse", sas: ["SAS 2A", "SAS 2B"] },
];
function buildRegulationSeed() {
  const grouped = new Set(REG_SEED_GROUPS.flatMap(g => g.sas));
  const out = [];
  SAS_REFERENTIEL.forEach(s => {
    const g = REG_SEED_GROUPS.find(x => x.sas[0] === s.code);
    if (g) { out.push({ code: g.code, nom: g.nom, sas: g.sas.slice() }); return; }
    if (grouped.has(s.code)) return;
    out.push({ code: defaultRegCode(s.code), nom: s.code + " · " + sasShortLabel(s), sas: [s.code] });
  });
  return out;
}
function loadRegulation() {
  try {
    const raw = localStorage.getItem(REG_KEY);
    if (raw) { const l = JSON.parse(raw); if (Array.isArray(l) && l.length) return l; }
  } catch (e) {}
  return buildRegulationSeed();
}
function saveRegulation(list) { try { localStorage.setItem(REG_KEY, JSON.stringify(list)); } catch (e) {} }
function isDefaultRegulation(t) { return t.sas.length === 1 && t.code === defaultRegCode(t.sas[0]); }
function regulationsOfSas(sasCode, list) { return (list || loadRegulation()).filter(t => (t.sas || []).includes(sasCode)); }

/* ------------------------------------------------------------------
   Rattachement d'une adresse à un territoire SAS (règle « script BI » corrigée)
   1. code commune dans une liste prédéfinie        → SAS de la liste
   2. département = préfixe du code commune         → SAS du département
   3. pas de code commune : département du code postal → SAS du département (approximatif)
      (pour un département découpé, recherche de la commune par son nom)
   4. sinon                                         → non rattaché
   ------------------------------------------------------------------ */
function normCommune(s) {
  return String(s || "").normalize("NFD").replace(/[̀-ͯ]/g, "").toUpperCase()
    .replace(/\bSAINTE\b/g, "STE").replace(/\bSAINT\b/g, "ST")
    .replace(/[^A-Z0-9]+/g, " ").trim();
}
const SAS_COMMUNE_INDEX = (() => {
  const byInsee = {}, byName = {};
  SAS_REFERENTIEL.forEach(s => (s.communes || []).forEach(([insee, nom]) => {
    byInsee[insee] = s.code;
    byName[s.dep + "|" + normCommune(nom)] = s.code;
  }));
  return { byInsee, byName };
})();
function depFromInsee(insee) {
  const c = String(insee || "").toUpperCase();
  if (/^(97|98)\d/.test(c)) return c.slice(0, 3);
  return c.slice(0, 2);
}
function depFromPostalCode(cp) {
  let c = String(cp || "").trim();
  if (/^\d{4}$/.test(c)) c = "0" + c;            // zéro de tête perdu
  if (!/^\d{5}$/.test(c)) return "";
  if (/^(97|98)/.test(c)) return c.slice(0, 3);
  if (c.startsWith("20")) return Number(c) < 20200 ? "2A" : "2B";  // Corse
  return c.slice(0, 2);
}
function sasOfDepartment(dep) {
  return SAS_REFERENTIEL.find(s => s.dep === dep && s.perimetre === "departement") || null;
}
function isSplitDepartment(dep) { return SAS_REFERENTIEL.some(s => s.dep === dep && s.perimetre === "communes"); }

/* Retourne { sas, regulation[], resolvedBy, approx } */
function resolveAddressTerritory(addr, regList) {
  const insee = normalizeInsee(addr && addr.insee);
  let sas = null, resolvedBy = "unassigned", approx = false;
  if (insee && SAS_COMMUNE_INDEX.byInsee[insee]) {
    sas = SAS_COMMUNE_INDEX.byInsee[insee]; resolvedBy = "commune";
  } else if (insee) {
    const s = sasOfDepartment(depFromInsee(insee));
    if (s) { sas = s.code; resolvedBy = "department"; }
    else if (isSplitDepartment(depFromInsee(insee))) resolvedBy = "unknown_insee";
  } else {
    const dep = depFromPostalCode(addr && addr.postalCode);
    if (dep && isSplitDepartment(dep)) {
      const hit = SAS_COMMUNE_INDEX.byName[dep + "|" + normCommune(addr.city)];
      if (hit) { sas = hit; resolvedBy = "commune_name"; approx = true; }
    } else if (dep) {
      const s = sasOfDepartment(dep);
      if (s) { sas = s.code; resolvedBy = "postal_code"; approx = true; }
    }
  }
  return { sas, regulation: sas ? regulationsOfSas(sas, regList) : [], resolvedBy, approx };
}
const RESOLVED_BY_LABEL = {
  commune: "par code INSEE (liste de communes)",
  department: "par département du code INSEE",
  commune_name: "par nom de commune (pas de code INSEE dans l'index)",
  postal_code: "par département du code postal (pas de code INSEE dans l'index)",
  unknown_insee: "code commune absent de la liste du département découpé (commune fusionnée ou code erroné) : à corriger dans la liste",
  unassigned: "non rattaché",
};

/* Code commune : zéros de tête restaurés, arrondissements de Paris / Lyon / Marseille ramenés à la commune */
function normalizeInsee(code) {
  let c = String(code ?? "").trim().toUpperCase();
  if (!c) return "";
  if (/^\d{4}$/.test(c)) c = "0" + c;
  if (/^751(0[1-9]|1\d|20)$/.test(c)) return "75056";
  if (/^6938[1-9]$/.test(c)) return "69123";
  if (/^132(0[1-9]|1[0-6])$/.test(c)) return "13055";
  return c;
}

/* ------------------------------------------------------------------
   Script Power BI « territory_department_num », reproduit à l'identique
   (pour comparaison avec la règle corrigée). Nécessite DAX_SPLITTED_LIST.
   ------------------------------------------------------------------ */
function daxTerritory(codePostal, codeCommune) {
  const list = (typeof DAX_SPLITTED_LIST !== "undefined") ? DAX_SPLITTED_LIST : [];
  const cp = String(codePostal ?? "").trim();
  const cc = String(codeCommune ?? "").trim();
  if (cp.length === 5) {
    if (cp.slice(0, 2).includes("97")) return { value: cp.slice(0, 3), branch: "Code postal 97x : 3 premiers caractères" };
    const byInsee = list.find(r => r[0] === cc);
    if (byInsee) return { value: byInsee[2], branch: "Code commune trouvé dans splitted_department_list" };
    const byCp = list.filter(r => r[1] === cp).map(r => r[2]).filter(Boolean).sort();
    if (byCp.length) return { value: byCp[0], branch: "Code postal trouvé dans splitted_department_list (FIRSTNONBLANK)" + (new Set(byCp).size > 1 ? " — code postal partagé entre " + [...new Set(byCp)].join(" et ") : "") };
    return { value: cp.slice(0, 2), branch: "2 premiers caractères du code postal" };
  }
  if (cp.length === 4) return { value: "0" + cp.slice(0, 1), branch: "Code postal sur 4 chiffres : « 0 » + 1er caractère" };
  return { value: "", branch: "Code postal absent ou invalide : vide" };
}
/* Sortie DAX → code SAS du référentiel (20A/20B = 2A/2B) */
function daxToSas(v) {
  if (!v) return "";
  const map = { "20A": "2A", "20B": "2B" };
  const code = "SAS " + (map[v] || v);
  return SAS_BY_CODE[code] ? code : "";
}
